WITH recent_order_items AS (SELECT * FROM order_items WHERE (unit_price > 310 AND product_id IS NOT NULL) OR quantity >= 4), product_id_summary AS (SELECT product_id, order_id, MAX(unit_price) AS max_unit_price, SUM(unit_price * quantity) AS revenue FROM recent_order_items GROUP BY product_id, order_id) SELECT * FROM product_id_summary WHERE max_unit_price >= 130 ORDER BY product_id DESC
